"""v19 synchronous Kaggle Save & Run All entrypoint; no detached processes."""
from pathlib import Path
import os,sys,json,gzip,base64,shutil,subprocess,hashlib,zipfile
os.environ['CUDA_VISIBLE_DEVICES']='0'
os.environ['TOKENIZERS_PARALLELISM']='false'
WORK=Path('/kaggle/working')
INPUT=Path('/kaggle/input/notebooks/trinashih/3beethoven-v0-2')
assert (INPUT/'3Beethoven_v17').is_dir(), 'Attach saved 3Beethoven-v0.2 Version 36 output'
REPO=WORK/'3Beethoven_v19'
shutil.copytree(INPUT/'3Beethoven_v17',REPO,dirs_exist_ok=True,ignore=shutil.ignore_patterns('__pycache__','.git'))
for rel,content in json.loads(gzip.decompress(base64.b64decode(''))).items():
 p=REPO/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
source=INPUT/'3beethoven_stats_v0_15'/'adapter'
assert source.is_dir(), 'Saved v15 adapter missing'
shutil.copytree(source,WORK/'3beethoven_stats_v0_15'/'adapter',dirs_exist_ok=True)
subprocess.run([sys.executable,'-m','pip','install','--quiet','transformers==5.0.0','peft==0.19.1','bitsandbytes==0.50.2','datasets==5.0.0','accelerate==1.13.0'],check=True)
subprocess.run([sys.executable,str(REPO/'scripts/run_stats_v0_19.py')],cwd=REPO,check=True)
ROOT=WORK/'3beethoven_stats_v0_19'
sys.path.insert(0,str(REPO/'scripts'))
from stats_curriculum_v0_19 import score,digest
from run_stats_v0_19 import DATA_SHA
from safetensors.torch import load_file
import torch
D=json.loads((ROOT/'frozen_questions.json').read_text());assert digest(D)==DATA_SHA
count=0
for path in list(ROOT.glob('v15_*.json'))+list(ROOT.glob('epoch_*_test.json'))+list(ROOT.glob('epoch_*/*validation.json')):
 key=next(k for k in D if k!='train' and path.name.endswith(k+'.json'))
 qs={q['id']:q for q in D[key]};rows=json.loads(path.read_text());assert len(rows)==len(qs)
 for r in rows:
  q=qs[r['id']];assert r['question_sha256']==digest(q);assert r['correct']==score(r['raw'],q)['correct']
 count+=len(rows)
weights={}
for path in ROOT.glob('epoch_*/adapter/adapter_model.safetensors'):
 state=load_file(str(path));assert state and all(torch.isfinite(v).all() for v in state.values())
 weights[str(path.relative_to(ROOT))]=hashlib.sha256(path.read_bytes()).hexdigest()
summary=json.loads((ROOT/'summary.json').read_text())
(ROOT/'verification.json').write_text(json.dumps(dict(responses=count,adapter_hashes=weights,summary_present=True,review_pending=summary['pending']),indent=2))
from flight_run_stats_v0_3 import package
package(ROOT)
archive=WORK/'3beethoven_stats_v0_19.zip'
with zipfile.ZipFile(archive) as z: assert z.testzip() is None
(WORK/'v19_backup_receipt.json').write_text(json.dumps(dict(bytes=archive.stat().st_size,sha256=hashlib.sha256(archive.read_bytes()).hexdigest(),crc_verified=True,adapter_hashes=weights),indent=2))
print('V19 VERIFIED AND PACKAGED',json.dumps(summary))
